import { describe, expect, it } from "vitest"

import type { Database } from "@/types/database"

import type { AdminDatabase } from "./admin"

type Written = AdminDatabase["public"]["Tables"]
type Generated = Database["public"]["Tables"]
type Shared = keyof Written & keyof Generated
// The rows carry an index signature; only their named columns count.
type Named<T> = keyof { [K in keyof T as string extends K ? never : number extends K ? never : K]: T[K] }

// A table or column the hand-written client types name that the migrations
// don't have (src/types/database.ts, regenerated by `pnpm db:types`): a query
// typed against it compiles and then fails. Columns left out are fine.
type Drifted =
  | Exclude<keyof Written, keyof Generated>
  | Exclude<keyof AdminDatabase["public"]["Functions"], keyof Database["public"]["Functions"]>
  | { [K in Shared]: [Exclude<Named<Written[K]["Row"]>, keyof Generated[K]["Row"]>] extends [never] ? never : K }[Shared]

describe("admin client types", () => {
  it("name no table or column the migrations lack", () => {
    // Fails to compile, naming the tables, once the hand-written types drift.
    const drifted: [Drifted] extends [never] ? "none" : Drifted = "none"
    expect(drifted).toBe("none")
  })
})
